head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.confirmYn = 0;
scwin.processGp;
scwin.vSetCntrCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        $c.cm.PanelToGroupBox(panel_Top);
        // PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);

        // 데이터셋 초기화
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/etn/EtnLstSprt.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_List_2",
            action : "/etn/EtnLstSprt.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 버튼 세팅
        btn_confirm.setDisabled(true);
        btn_confirm.setBackgroundImage("../img/btn_approval_d.gif");
        btn_return.setDisabled(true);
        btn_return.setBackgroundImage("../img/btn_Ret_d.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        /**********************************************
         * Event   : btn_Search > OnClick
         * 설명    : 조회버튼 클릭
         ***********************************************/
        // 보증인 목록조회
        await scwin.listSearch();
        if (scwin.vSetCntrCd !== 1) {
            $c.lce.fn_SetSrtyCombo("ULDSTF41095.xml", dts_Cntrcd, '01371'); // 국가 01371
            scwin.vSetCntrCd = 1;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
