         * 설명    : 발행기관 조회팝업
         ***********************************************/
        scwin.getPar = scwin.getParSrty;
        fn_SetPar = scwin.setParSrty;
        $c.lce.fn_PopSrtySearch(img_com_srch);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41095.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        /**********************************************
         * 함수명   : txb_ISUR_CD > onblur
         * 설명      : 발행기관 코드 변경
         ***********************************************/
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41095.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_confirm_onclick = function() {
    try {
        /**********************************************
         * Event   : btn_confirm > OnClick
         * 설명    : 승인버튼 클릭
         ***********************************************/
        scwin.processGp = SCREN_PROCS_TP_CD_03;
        scwin.update(1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41095.btn_confirm_onclick" });
    }
};

/**
 * @method
