/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnFail = async function() {
    try {
        /**********************************************
         * Event   : trs_save > OnFail
         * 설명    : 저장 에러시 처리
         ***********************************************/
        if (scwin.processGp === SCREN_PROCS_TP_CD_03) {
            if (scwin.confirmYn === 1) {
                await $c.win.alert($c.stf.getMessageParam("MSG-A002", "승인"));
            } else if (scwin.confirmYn === 2) {
                await $c.win.alert($c.stf.getMessageParam("MSG-A002", "반송"));
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        /**********************************************
         * Event   : trs_save > OnSuccess
         * 설명    : 저장 성공시 처리
         ***********************************************/
        // 버튼 세팅
        btn_confirm.setDisabled(false);
        btn_confirm.setBackgroundImage("../img/btn_approval_d.gif");
        btn_return.setDisabled(false);
        btn_return.setBackgroundImage("../img/btn_Ret_d.gif");

        // 메세지처리
        // alert(getMessageParam("MSG-0001"));
        // 조회
        await scwin.listSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_List_1_OnRowPosChanged
 * @description List 1 On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnRowPosChanged = async function(row) {
    try {
        /**********************************************
         * Event   : dts_List_1 > OnRowPosChanged
         * 설명    : 그리드 위치 변경시 세팅
         ***********************************************/
        await scwin.searchDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095.dts_List_1_OnRowPosChanged" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setSrtyCombo
 * @description 콤보데이터를 설정한다.
 * @param {*} "ULDSTF41095.xml" "ULDSTF41095.xml"
 * @param {*} dtsObj dtsObj
 * @param {*} CD_ID_M CD_ID_M
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSrtyCombo = async function("ULDSTF41095.xml", dtsObj, CD_ID_M) {
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + "ULDSTF41095.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M='CNTR_CD'";
    dtsObj.SyncLoad = "true";
    const sbmOptions = {
        id : "sbm_dtsObj",
        action : "/CodeAction.do",
        ref : "",
        target : "dtsObj=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSearch
 * @description 보증인관리 목록조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSearch = async function() {
    let vSrtyStatusCd = cmb_sch_srty_stat_cd.getValue();
    if (vSrtyStatusCd === "A") {
        vSrtyStatusCd = '';
    } else if (vSrtyStatusCd === "B") {
        vSrtyStatusCd = 0;
    } else if (vSrtyStatusCd === "C") {
        vSrtyStatusCd = 1;
    }
    url += "&SCREN_ID=" + "ULDSTF41095.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&outputMessageId=ETN_SRTY_LIST";
    url += "&COM_NM=" + txb_com_abbrv.getValue();
    url += "&APPL_PROCS_TP_CD=" + vSrtyStatusCd;
    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/etn/EtnLstSprt.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ShowWin(grd_List);
    return url;
};

/**
 * @method
 * @name searchDetail
 * @description 보증인관리 상세조회
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function(row) {
    url += "&SCREN_ID=" + "ULDSTF41095.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&outputMessageId=ETN_SRTY_LISTDETAIL";
    url += "&SRTY_CD=" + dts_List_1.getCellData(row, "SRTY_CD");
    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/etn/EtnLstSprt.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const gubun = dts_List_1.getCellData(row, "APPL_PROCS_TP_NM");
    if (gubun === "승인" || gubun === undefined) {
        btn_confirm.setDisabled(true);
        btn_confirm.setBackgroundImage("../img/btn_approval_d.gif");
        btn_return.setDisabled(true);
        btn_return.setBackgroundImage("../img/btn_Ret_d.gif");
    } else {
        btn_confirm.setDisabled(false);
        btn_confirm.setBackgroundImage("../img/btn_approval.gif");
        btn_return.setDisabled(false);
        btn_return.setBackgroundImage("../img/btn_Ret.gif");
    }
    return url;
};

/**
 * @method
 * @name chkSrtyCd
 * @description 보증인관리 코드존재여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkSrtyCd = async function() {
    url += "&outputMessageId=ETN_SRTY_LISTDETAIL";
    url += "&SCREN_ID=" + "ULDSTF41095.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRTY_CD=" + edt_srty_cd.getValue(); //

    const sbmOptions = {
        id : "sbm_dts_ChkCd",
        action : "/etn/EtnLstSprt.do",
        ref : "",
        target : "dts_ChkCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_ChkCd.getCellData(0, "SRTY_CD") === null) {
        return false;
    } else {
        return true;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name update
 * @description 보증인정보 수정
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.update = function(gubun) {
    scwin.confirmYn = gubun;
    if (scwin.confirmYn === 1) {
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", "승인"))) return;
    } else if (scwin.confirmYn === 2) {
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", "반송"))) return;
    }
    let url = "/etn/EtnLstSprt.do?method=saveSrtyDtl";
    url += "&SCREN_ID=" + "ULDSTF41095.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    dts_List_2.setCellData(1, "APPL_PROCS_TP_CD", scwin.confirmYn);
    trs_save.Action = $c.lce.fn_encodeNSession(url);
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List_2)";
    trs_save.Post();
};

/**
 * @method
 * @name checkForm
 * @description 보증인정보 Validation
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_srty_cd.getValue() === "") {
        await $c.win.alert("보증인코드를 입력하세요");
        edt_srty_cd.focus();
        return false;
    }
    if (!$c.lce.fn_getCheckByte('보증인코드', edt_srty_cd.getValue(), 5)) return false;
    if (txb_srty_nm.getValue() === "") {
        await $c.win.alert("[보증인명]을 입력하세요.");
        txb_srty_nm.focus();
        return false;
    }
    if (!$c.lce.fn_getCheckByte('보증인명', txb_srty_nm.getValue(), 100)) return false;
    if (!$c.lce.fn_getCheckByte('보증인약명', txb_srty_abbrv.getValue(), 50)) return false;
    const pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    let str = txb_srty_eng_nm.getValue();
    for (let i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            await $c.win.alert('영문보증인명에 한글은 사용할 수 없습니다');
            txb_srty_eng_nm.focus();
            return false;
        }
    }
    if (!$c.lce.fn_getCheckByte('영문보증인명', txb_srty_eng_nm.getValue(), 100)) return false;
    let str = txb_srty_eng_abbrv.getValue();
    for (let i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            await $c.win.alert('영문보증인약명에 한글은 사용할 수 없습니다');
            txb_srty_eng_abbrv.focus();
            return false;
        }
    }
    if (!$c.lce.fn_getCheckByte('영문보증인약명', txb_srty_eng_abbrv.getValue(), 50)) return false;

    // 자리수 체크
    if (!$c.lce.fn_getCheckByte('주소', txb_addr.getValue(), 200)) return false;
    if (!$c.lce.fn_getCheckByte('보증인종류', txb_srty_kind_contn.getValue(), 40)) return false;
    return true;
};

/**
 * @method
 * @name getParSrty
 * @description 보증인 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParSrty = function(arrPar) {
    arrPar[0] = {
        SRTY_CD: txb_isur_cd.getValue(),
        SRTY_NM: txb_com_abbrv.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParSrty
 * @description 보증인 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParSrty = function(arrPar) {
    if (typeof(arrPar[0].SRTY_CD) !== 'undefined') {
        txb_isur_cd.setValue(arrPar[0].SRTY_CD);
        txb_com_abbrv.setValue(arrPar[0].SRTY_NM);
    }
};
